function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function q(sel,root=document){return root.querySelector(sel)}
function qa(sel,root=document){return [...root.querySelectorAll(sel)]}
function safeSpeak(text){try{if(typeof speak==="function")return speak(text,.67);if("speechSynthesis" in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="en-US";u.rate=.72;speechSynthesis.speak(u)}}catch(_){}}
function notify(text){try{if(typeof toast==="function")toast(text);else console.log(text)}catch(_){}}
function addStars(n=2){try{if(typeof course!=="undefined"){course.stars=Number(course.stars||0)+n;if(typeof saveCourse==="function")saveCourse();if(typeof render==="function")render()}}catch(_){}}
function tokenDone(t){try{return typeof completedSet==="function"?completedSet().has(t):false}catch(_){return false}}
function markToken(t,stars=2){try{if(typeof course==="undefined")return;if(!Array.isArray(course.completed))course.completed=[];if(!course.completed.includes(t)){course.completed.push(t);course.stars=Number(course.stars||0)+stars;if(typeof saveCourse==="function")saveCourse();notify(`Great job! +${stars} stars ⭐`)}}catch(e){console.warn(e)}}

